let applyingRemote=false,lastRemoteView='';const online=()=>Boolean(window.Room?.active);const myPlayer=()=>online()?window.Room.role:null;const report=e=>{$('#connection-status').textContent=e.message||String(e);};
const C=window.NIGHT_CONTENT,$=s=>document.querySelector(s),KEY='wahala-night-v1';
const fresh=()=>({ready:{shazily:false,anike:false},started:false,done:[],seen:[],slide:0,objections:{shazily:0,anike:0},chat:[],quoteRound:0,quoteAnswers:{},scores:{shazily:0,anike:0},replyRound:0,replyAnswers:{},storyRound:0,storyAnswers:{},softRound:0,softAnswers:{},traps:[],jury:{}});
let S;try{S=JSON.parse(localStorage.getItem(KEY))||fresh();}catch{S=fresh();}S.jury??={};let current='',timer=null,remaining=40,paused=false,voice=false;
const modules=[['opening','The Small Small Wahala Hearings','15 scenes. Real receipts. A ten-minute opening roast.'],['quotes','Whose mouth was this?','Both of you guess. Then we show who actually said it.'],['traps','You think I have forgotten?','Set a question. Hide the answer. Predict what they will miss.'],['replies','Finish my reply','Write the next line. Compare both guesses with the receipt.'],['stories','The forgotten files','Four little memories. Your answers finish the story.'],['soft','The soft part, finally','Four private reflections. Reveal them together. No scoring.']];
const name=id=>id==='anike'?'Anike':'Shazily',other=id=>id==='anike'?'shazily':'anike';
function save(){if(online()&&!applyingRemote)window.Room.patch({current,ready:S.ready,done:S.done,seen:S.seen,slide:S.slide,objections:S.objections,quoteRound:S.quoteRound,replyRound:S.replyRound,storyRound:S.storyRound,softRound:S.softRound,started:S.started}).catch(report);localStorage.setItem(KEY,JSON.stringify(S));$('#overall').textContent=S.done.length+' / 6 experiences';$('#chat-count').textContent=S.chat.length;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function stop(){clearInterval(timer);timer=null;if('speechSynthesis' in window)speechSynthesis.cancel();}
function page(which){for(const id of ['lobby','hub','experience'])$('#'+id).hidden=id!==which;}
function complete(id){if(!S.done.includes(id)){S.done.push(id);save();}}
function hub(){stop();current='';page('hub');$('#hub-cards').innerHTML=modules.map(([id,title,copy],i)=>`<button class="hub-card ${S.done.includes(id)?'complete':''}" data-module="${id}"><span class="number">0${i+1}</span><span class="status">${S.done.includes(id)?'COMPLETED ✓':progressLabel(id)}</span><h3>${esc(title)}</h3><p>${esc(copy)}</p></button>`).join('');$('#all-done')?.remove();if(S.done.length===6)$('#hub-cards').insertAdjacentHTML('afterend','<p class="toast" id="all-done">Every experience completed. You can replay any section. Now go and gist. ❤️</p>');save();}
function progressLabel(id){const n=id==='opening'?S.seen.length:id==='quotes'?S.quoteRound:id==='replies'?S.replyRound:id==='stories'?S.storyRound:id==='soft'?S.softRound:S.traps.filter(t=>t.finished).length;const total=id==='opening'?15:id==='quotes'?8:id==='traps'?2:4;return n?n+' / '+total+' EXPLORED':'NOT STARTED';}
function open(id){stop();current=id;page('experience');$('#section-name').textContent=modules.find(m=>m[0]===id)[1];render();scrollTo(0,0);}
function render(){if(current==='opening')renderSlide();else if(current==='quotes')renderQuotes();else if(current==='traps')renderTraps();else if(current==='replies')renderWritten('reply');else if(current==='stories')renderWritten('story');else renderWritten('soft');protectPlayerControls();save();}
function narrate(text){if(!voice||!('speechSynthesis' in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.95;speechSynthesis.speak(u);}
function juryHTML(i){const questions={6:'Who is the most jealous? Let the accused vote.',9:'Who gets your most-famous award?',13:'Who is the most interesting character in this relationship?'};if(!questions[i])return '';const a=S.jury[i]||{},both=typeof a.shazily==='string'&&typeof a.anike==='string';return `<div class="jury"><p class="eyebrow">THE JURY GETS A SAY / YOUR VOTES, NOT A CHAT DIAGNOSIS</p><h3>${esc(questions[i])}</h3>${['shazily','anike'].map(id=>`<div class="player-answer"><label>${name(id)}’s ballot</label>${a[id]?'<p>Ballot locked.</p>':`<div class="choices">${['shazily','anike','both'].map(v=>`<button class="choice" data-jury="${i}" data-voter="${id}" data-nominee="${v}">${v==='both'?'Both, obviously':name(v)}</button>`).join('')}</div>`}</div>`).join('')}${both?`<div class="result"><p>Shazily nominated: ${a.shazily==='both'?'Both':name(a.shazily)}.</p><p>Anike nominated: ${a.anike==='both'?'Both':name(a.anike)}.</p><p>You may now defend your answer in the gist corner. 😹</p></div>`:''}</div>`;}
function renderSlide(){clearInterval(timer);const i=S.slide,s=C.slides[i];if(!S.seen.includes(i))S.seen.push(i);if(S.seen.length===15)complete('opening');remaining=online()?Math.ceil((window.Room.state.playback.paused?window.Room.state.playback.remaining:Math.max(0,window.Room.state.playback.deadline-Date.now()))/1000):40;paused=online()?window.Room.state.playback.paused:false;$('#section-progress').textContent=S.seen.length+' / 15 scenes';
$('#stage').innerHTML=`<article class="slide"><p class="eyebrow">${esc(s.tag)}</p><h2>${esc(s.title)}</h2><p class="verdict">${esc(s.verdict)}</p><p class="slide-copy">${esc(s.body)}</p>${s.stat?`<div class="stat">${esc(s.stat)}</div>`:''}${s.bars?`<div class="bars">${s.bars.map((n,j)=>`<div class="bar-row"><span>${s.labels[j]}</span><div class="bar"><i style="width:${n/Math.max(...s.bars)*100}%"></i></div><span>${n.toLocaleString()}</span></div>`).join('')}</div>`:''}<div class="receipts">${s.receipt.map(t=>`<div class="receipt">${esc(t)}</div>`).join('')}</div><p class="footnote">${esc(s.foot)}</p>${juryHTML(i)}</article><div class="slide-controls"><div class="control-group"><button data-action="prev" ${i===0?'disabled':''}>← Previous</button><button data-action="pause">${paused?'Resume':'Pause'}</button><button data-action="next">${i===14?'Back to the night':'Next →'}</button><span class="timer">00:${String(remaining).padStart(2,'0')}</span></div><div class="control-group"><button data-objection="shazily">Shazily objects (${S.objections.shazily})</button><button data-objection="anike">Anike objects (${S.objections.anike})</button><button data-action="voice" aria-pressed="${voice}">${voice?'Voice on':'Read aloud'}</button></div></div><p class="toast" id="objection-note" role="status"></p><div class="timeline" aria-label="Presentation scenes">${C.slides.map((_,j)=>`<button data-slide="${j}" class="${S.seen.includes(j)?'seen':''} ${j===i?'current':''}" aria-label="Scene ${j+1}" ${j===i?'aria-current="step"':''}></button>`).join('')}</div>`;
narrate(s.title+'. '+s.verdict+'. '+s.body);timer=setInterval(()=>{if(paused)return;remaining=online()?Math.ceil(Math.max(0,window.Room.state.playback.deadline-Date.now())/1000):remaining-1;$('.timer').textContent='00:'+String(Math.max(remaining,0)).padStart(2,'0');if(remaining<=0){if(online()){window.Room.advance().catch(report);return;}if(S.slide<14){S.slide++;render();}else{stop();$('.timer').textContent='Hearing concluded';}}},1000);}
function endCard(id,title){complete(id);$('#section-progress').textContent='Completed';$('#stage').innerHTML=`<div class="completion"><p class="eyebrow">EXPERIENCE COMPLETE</p><h2>${esc(title)}</h2><p>Your progress is saved. Choose the next experience, or replay this one.</p><button class="primary" data-action="hub">Back to our night</button> <button class="pill" data-action="replay">Replay</button></div>`;}
function renderQuotes(){if(S.quoteRound>=C.quotes.length)return endCard('quotes','Both mouths have been accounted for.');const q=C.quotes[S.quoteRound],a=S.quoteAnswers[S.quoteRound]||{};$('#section-progress').textContent=(S.quoteRound+1)+' / 8';const both=typeof a.shazily==='string'&&typeof a.anike==='string';$('#stage').innerHTML=`<article class="game-card"><p class="eyebrow">WHO SAID THIS? / ANSWERS REVEAL TOGETHER</p><h2>${online()?esc(name(other(myPlayer())))+' asks:':'Whose mouth'}<br>${online()?(myPlayer()==='anike'?'Anike, who said it?':'Oga, whose mouth? 🌚'):'was this?'}</h2><blockquote>“${esc(q[0])}”</blockquote>${['shazily','anike'].map(id=>`<div class="player-answer"><label>${name(id)}’s guess ${a[id]?'· LOCKED':''}</label>${a[id]?'<p>Answer locked. No changing your story.</p>':`<div class="choices"><button class="choice" data-guess="shazily" data-player="${id}">Shazily</button><button class="choice" data-guess="anike" data-player="${id}">Anike</button></div>`}</div>`).join('')}${both?`<div class="result"><p><b>${name(q[1])}</b> said it. ${esc(q[2])}.</p><p>Shazily guessed ${name(a.shazily)}. Anike guessed ${name(a.anike)}.</p></div><button class="primary" data-action="quote-next">Next receipt →</button>`:''}<div class="scores"><span>Shazily: ${S.scores.shazily}</span><span>Anike: ${S.scores.anike}</span></div></article>`;}
const softPrompts=['One ordinary thing you do that makes me feel loved.','One moment I felt proud of you.','One memory I want us to make next.','One du’a I am making for you this year.'];
function personalPrompt(type,r,recipient){const from=other(recipient);const prefix=from==='anike'?'Oga':'Anike';if(type==='soft'){const q=['what small thing do I do that makes you feel loved?','when was a moment you felt proud of me?','what memory do you want us to make next?','what du’a are you making for me this year?'][r];return prefix+', '+q+(from==='anike'?' 🤭':' ❤️');}if(type==='story'){const q=['what tiny detail of our Maryland day do you still remember?','what made you smile at Ozone?','which of our Unilag moments would you repeat?','which small thing I do makes you feel loved?'][r];return prefix+', '+q+(from==='anike'?' 🌚':' 😌');}return prefix+', can you remember what came next in this gist? '+(from==='anike'?'No forming o. 😹':'I want to see your answer. 🤭');}
function renderWritten(type){const field=type+'Round',answers=type+'Answers',r=S[field],total=4;if(r>=total)return endCard(current,type==='soft'?'Keep these words. They are yours.':'Another part of your story, remembered.');const item=type==='reply'?C.replies[r]:type==='story'?C.stories[r]:null;const title=type==='reply'?'Finish my reply.':type==='story'?item[0]:'The soft part.';const prompt=type==='reply'?item[0]:type==='story'?item[2]:softPrompts[r];const a=S[answers][r]||{},both=typeof a.shazily==='string'&&typeof a.anike==='string';$('#section-progress').textContent=(r+1)+' / 4';$('#stage').innerHTML=`<article class="game-card"><p class="eyebrow">${type==='reply'?'WRITE WHAT CAME NEXT':type==='story'?'YOU FINISH THE MEMORY':'NO POINTS. JUST BOTH OF YOU.'}</p><h2>${esc(title)}</h2>${type==='story'?`<p class="story-copy">${esc(item[1])}</p>`:''}<blockquote>${esc(prompt)}</blockquote>${['shazily','anike'].map(id=>`<div class="player-answer"><label>${name(other(id))} asks ${name(id)} ${a[id]?'· ANSWER LOCKED':''}</label><p class="small">${esc(personalPrompt(type,r,id))}</p>${a[id]?'<p>Kept safe until both answers are in.</p>':`<form class="written-form" data-player="${id}" data-type="${type}"><label class="sr-only" for="answer-${id}">${name(id)}’s answer</label><textarea id="answer-${id}" name="answer" maxlength="1800" required placeholder="Take your time…"></textarea><button class="primary">Lock my answer</button></form>`}</div>`).join('')}${both?`<div class="result"><p><b>Shazily</b><br>${esc(a.shazily).replace(/\n/g,'<br>')}</p><p><b>Anike</b><br>${esc(a.anike).replace(/\n/g,'<br>')}</p>${type==='reply'?`<p><b>The actual reply</b><br>${esc(item[1])}</p><p class="small">Decide together whose guess sounded most like the original.</p>`:''}</div><button class="primary" data-action="written-next" data-type="${type}">${r===3?'Finish this chapter':'Next →'}</button>`:'<p class="small">On one screen, pass the phone before writing. Answers reveal together.</p>'}</article>`;}
function renderTraps(){const finished=S.traps.filter(t=>t.finished).length;$('#section-progress').textContent=finished+' / 2 authors completed';if(finished>=2)return endCard('traps','The memory traps have been sprung.');const pending=S.traps.find(t=>!t.finished);if(!pending){const available=['shazily','anike'].filter(id=>!S.traps.some(t=>t.author===id));$('#stage').innerHTML=`<article class="game-card"><p class="eyebrow">${online()?name(myPlayer()).toUpperCase()+' ASKS THEIR PERSON':'SET A MEMORY TRAP'}</p><h2>You think I’ve<br>forgotten?</h2><p>Each person writes a question. Supply the answer, and predict whether your person will remember. Keep the screen to yourself while writing.</p><form id="trap-form" class="stack"><label>Question author <select name="author">${available.map(id=>`<option value="${id}">${name(id)}</option>`).join('')}</select></label><div class="choices">${(C.prompts[online()?myPlayer():available[0]]||[]).map((q,i)=>`<button type="button" class="pill" data-suggestion="${i}">Prompt ${i+1}</button>`).join('')}</div><label>Your question<textarea id="trap-question" name="question" maxlength="1000" required placeholder="Which detail do you think I have forgotten?"></textarea></label><label>The answer<input id="trap-answer" name="answer" maxlength="1000" required></label><label>Your prediction <select name="prediction"><option value="forget">They will forget 🌚</option><option value="remember">They will remember ❤️</option></select></label><button class="primary">${online()?'Send my question. Hide my answer.':'Hide my answer. Pass the phone.'}</button></form></article>`;return;}
$('#stage').innerHTML=`<article class="game-card"><p class="eyebrow">${name(pending.author).toUpperCase()} SET THIS TRAP</p><h2>${name(other(pending.author))},<br>prove it.</h2><div class="question-box">${esc(pending.question)}</div>${!pending.guess?`<form id="trap-guess" class="stack"><label>Your answer<textarea name="guess" maxlength="1000" required></textarea></label><button class="primary">Lock it. Reveal the evidence.</button></form>`:`<div class="result"><p><b>The guess</b><br>${esc(pending.guess)}</p><p><b>The expected answer</b><br>${esc(pending.answer||'Revealing the expected answer…')}</p><p>${name(pending.author)} predicted: “They will ${pending.prediction}.”</p></div><p>${name(pending.author)}, accept the answer yourself. Spelling is not the point.</p><div class="choices"><button class="primary" data-trap-result="remember">They remembered ❤️</button><button class="pill" data-trap-result="forget">They forgot 🌚</button></div>`}</article>`;}
function chatRender(){const log=$('#chat-messages');log.innerHTML=S.chat.map(m=>`<div class="chat-message ${m.by}"><b>${name(m.by)}</b>${m.context?`<span class="chat-context">${esc(m.context)}</span>`:''}${esc(m.text).replace(/\n/g,'<br>')}</div>`).join('');log.scrollTop=log.scrollHeight;save();}
function contextLabel(){return current==='opening'?'Presentation · scene '+(S.slide+1):current==='quotes'?'Quiz · round '+(S.quoteRound+1):current==='replies'?'Finish my reply · round '+(S.replyRound+1):current==='stories'?'Forgotten files · chapter '+(S.storyRound+1):current==='soft'?'Soft part · prompt '+(S.softRound+1):current==='traps'?'Memory trap':'Our night';}
function addChat(by,text){if(online()){window.Room.chat(text,contextLabel()).catch(report);return;}S.chat.push({by,text,context:contextLabel(),time:Date.now()});if(S.chat.length>150)S.chat.shift();chatRender();}
$('#begin').addEventListener('click',()=>{if(!S.ready.shazily||!S.ready.anike)return;S.started=true;save();open('opening');});
document.querySelectorAll('[data-ready]').forEach(b=>{b.setAttribute('aria-pressed',String(S.ready[b.dataset.ready]));b.addEventListener('click',()=>{const id=b.dataset.ready;S.ready[id]=!S.ready[id];b.setAttribute('aria-pressed',String(S.ready[id]));readyUI();save();});});
function readyUI(){const ready=S.ready.shazily&&S.ready.anike;$('#begin').disabled=!ready;$('#begin').textContent=ready?'Both present. Open the hearing.':'Waiting for both defendants';}readyUI();$('#resume').hidden=!S.started;
$('#resume').addEventListener('click',hub);$('#home').addEventListener('click',e=>{e.preventDefault();S.started?hub():page('lobby');});$('#back-hub').addEventListener('click',hub);
$('#reset').addEventListener('click',()=>{if(online()){report(new Error('Create a new room to start a fresh online night. The existing room is kept.'));return;}if(!confirm('Clear this rehearsal’s answers, chat, and progress?'))return;stop();S=fresh();save();location.reload();});
document.addEventListener('click',e=>{const suggestion=e.target.closest('[data-suggestion]');if(suggestion){const author=online()?myPlayer():document.querySelector('[name=author]').value,q=C.prompts[author][Number(suggestion.dataset.suggestion)];document.querySelector('[name=question]').value=q.question;document.querySelector('[name=answer]').value=q.answer;}const ballot=e.target.closest('[data-jury]');if(ballot){if(online()){window.Room.submit('jury-'+S.slide,'jury',ballot.dataset.nominee).catch(report);return;}const i=ballot.dataset.jury;S.jury[i]??={};S.jury[i][ballot.dataset.voter]=ballot.dataset.nominee;const wasPaused=paused;renderSlide();paused=wasPaused;if(paused)document.querySelector('[data-action=\"pause\"]').textContent='Resume';save();}const m=e.target.closest('[data-module]');if(m)open(m.dataset.module);const slide=e.target.closest('[data-slide]');if(slide){if(online()){window.Room.playback({slide:Number(slide.dataset.slide)}).catch(report);return;}S.slide=Number(slide.dataset.slide);render();}const o=e.target.closest('[data-objection]');if(o){const id=o.dataset.objection;S.objections[id]++;o.textContent=name(id)+' objects ('+S.objections[id]+')';$('#objection-note').textContent=name(id)+', your objection has been received. The receipt has not disappeared. 😹';addChat(id,'Objection to scene '+(S.slide+1)+'! The court should hear my side. 😹');save();}const g=e.target.closest('[data-guess]');if(g){if(online()){window.Room.submit('quote-'+S.quoteRound,'quote',g.dataset.guess).catch(report);return;}const r=S.quoteRound;S.quoteAnswers[r]??={};if(S.quoteAnswers[r][g.dataset.player])return;S.quoteAnswers[r][g.dataset.player]=g.dataset.guess;if(g.dataset.guess===C.quotes[r][1])S.scores[g.dataset.player]++;render();}const tr=e.target.closest('[data-trap-result]');if(tr){if(online()){const t=S.traps.find(t=>!t.finished);window.Room.grade(t.author,tr.dataset.trapResult).catch(report);return;}const t=S.traps.find(t=>!t.finished);t.finished=true;t.result=tr.dataset.trapResult;render();}const a=e.target.closest('[data-action]')?.dataset.action;if(a==='hub')hub();if(a==='prev'){if(online()){window.Room.playback({slide:Math.max(0,S.slide-1)}).catch(report);return;}S.slide=Math.max(0,S.slide-1);render();}if(a==='next'){if(online()&&S.slide<14){window.Room.playback({slide:S.slide+1}).catch(report);return;}if(S.slide===14)hub();else{S.slide++;render();}}if(a==='pause'){if(online()){window.Room.playback({pause:!paused}).catch(report);return;}paused=!paused;e.target.textContent=paused?'Resume':'Pause';if(paused&&'speechSynthesis'in window)speechSynthesis.pause();else if('speechSynthesis'in window)speechSynthesis.resume();}if(a==='voice'){if(!('speechSynthesis'in window)){$('#objection-note').textContent='Read-aloud is unavailable in this browser.';return;}voice=!voice;e.target.textContent=voice?'Voice on':'Read aloud';e.target.setAttribute('aria-pressed',String(voice));if(voice)narrate(C.slides[S.slide].title+'. '+C.slides[S.slide].body);else speechSynthesis.cancel();}if(a==='quote-next'){S.quoteRound++;render();}if(a==='written-next'){S[e.target.dataset.type+'Round']++;render();}if(a==='replay'){if(online()){report(new Error('Locked answers stay saved in this room. Create a new room for a fresh replay.'));return;}if(current==='quotes'){S.quoteRound=0;S.quoteAnswers={};S.scores={shazily:0,anike:0};}if(current==='replies'){S.replyRound=0;S.replyAnswers={};}if(current==='stories'){S.storyRound=0;S.storyAnswers={};}if(current==='soft'){S.softRound=0;S.softAnswers={};}if(current==='traps')S.traps=[];render();}if(e.target.closest('[data-close]'))e.target.closest('dialog').close();});
document.addEventListener('submit',e=>{if(e.target.matches('.written-form')){e.preventDefault();const f=e.target,t=f.dataset.type,r=S[t+'Round'],value=new FormData(f).get('answer').trim();if(!value)return;if(online()){window.Room.submit(t+'-'+r,t,value).catch(report);return;}S[t+'Answers'][r]??={};S[t+'Answers'][r][f.dataset.player]=value;render();}if(e.target.id==='trap-form'){e.preventDefault();const f=new FormData(e.target),question=f.get('question').trim(),answer=f.get('answer').trim();if(!question||!answer)return;if(online()){window.Room.question(question,answer,f.get('prediction')).catch(report);return;}S.traps.push({author:f.get('author'),question,answer,prediction:f.get('prediction'),finished:false});render();}if(e.target.id==='trap-guess'){e.preventDefault();const value=new FormData(e.target).get('guess').trim();if(!value)return;if(online()){const t=S.traps.find(t=>!t.finished);window.Room.submit('trap-'+t.author,'trap',value).catch(report);return;}S.traps.find(t=>!t.finished).guess=value;render();}});
function chatToggle(open){$('#chat-panel').hidden=!open;$('#chat-toggle').setAttribute('aria-expanded',String(open));if(open){chatRender();$('#chat-input').focus();}}$('#chat-toggle').addEventListener('click',()=>chatToggle($('#chat-panel').hidden));$('#chat-close').addEventListener('click',()=>chatToggle(false));$('#chat-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#chat-input'),text=input.value.trim();if(!text)return;addChat($('#chat-speaker').value,text);input.value='';});
$('#method-open').addEventListener('click',()=>{const m=C.method;$('#method-body').innerHTML=`<p>${esc(m.period)}. Anike: ${m.textMessages.anike.toLocaleString()} retained texts. Shazily: ${m.textMessages.shazily.toLocaleString()}.</p><p>${esc(m.definition)}</p><table><thead><tr><th>Message contains</th><th>Anike</th><th>Shazily</th></tr></thead><tbody>${Object.entries(m.matches).map(([k,v])=>`<tr><td>${esc(v.pattern)}</td><td>${v.anike}</td><td>${v.shazily}</td></tr>`).join('')}</tbody></table><p class="small">All percentages use the denominator stated on the scene. “Most famous”, “most jealous”, and “most interesting” cannot be established from these counts. The titles are jokes with receipts.</p>`;$('#method-dialog').showModal();});
save();chatRender();

function protectPlayerControls(){if(!online())return;const me=myPlayer();document.querySelectorAll('[data-player],[data-voter],[data-objection]').forEach(b=>{const who=b.dataset.player||b.dataset.voter||b.dataset.objection;if(who!==me){if(b.tagName==='FORM')b.innerHTML='<p class="small">Waiting for '+name(who)+' to lock their answer.</p>';else b.disabled=true;}});document.querySelectorAll('[data-ready]').forEach(b=>{b.disabled=b.dataset.ready!==me;b.setAttribute('aria-pressed',String(S.ready[b.dataset.ready]));});const author=document.querySelector('[name="author"]');if(author){for(const o of author.options)o.disabled=o.value!==me;author.value=me;}const t=S.traps.find(t=>!t.finished);if(t&&t.author===me&&document.querySelector('#trap-guess'))document.querySelector('#trap-guess').innerHTML='<p class="small">Waiting for '+name(other(me))+' to answer.</p>';if(t&&t.author!==me)document.querySelectorAll('[data-trap-result]').forEach(b=>b.disabled=true);$('#chat-speaker').value=me;$('#chat-speaker').disabled=true;}
window.addEventListener('roomerror',e=>report(new Error(e.detail)));
window.addEventListener('roomstate',e=>{const d=e.detail;if(!d.state)return;applyingRemote=true;const view=JSON.stringify({state:d.state,rounds:d.rounds,answers:d.answers,secrets:d.secrets,questions:d.questions});const changed=view!==lastRemoteView;lastRemoteView=view;Object.assign(S,structuredClone(d.state));S.jury={};S.quoteAnswers={};S.replyAnswers={};S.storyAnswers={};S.softAnswers={};S.scores={shazily:0,anike:0};for(const [round,info]of Object.entries(d.rounds)){const values={};for(const role of ['shazily','anike'])if(info.locked?.[role])values[role]=d.answers[round]?.[role]??true;const [kind,index]=round.split('-');const target={jury:'jury',quote:'quoteAnswers',reply:'replyAnswers',story:'storyAnswers',soft:'softAnswers'}[kind];if(target)S[target][index]=values;if(kind==='quote'&&typeof values.shazily==='string'&&typeof values.anike==='string')for(const role of ['shazily','anike'])if(values[role]===C.quotes[Number(index)][1])S.scores[role]++;}S.traps=Object.entries(d.questions).map(([author,q])=>({...q,author,answer:d.secrets['trap-'+author],guess:d.answers['trap-'+author]?.[other(author)]}));S.chat=d.messages;const connected=Boolean(d.members?.shazily&&d.members?.anike);$('#connection-status').textContent=connected?'Both connected. This night is shared.':'Connected as '+name(d.role)+'. Waiting for your person to join.';$('#invitation').hidden=false;$('#invite-link').value=window.Room.invite();$('#room-role').value=d.role;$('#room-role').disabled=true;readyUI();protectPlayerControls();const drafts={};document.querySelectorAll('textarea,input').forEach(el=>{if(el.id&&el.value)drafts[el.id]=el.value;});if(changed){stop();current=d.state.current;if(d.state.started){page(current?'experience':'hub');if(current){$('#section-name').textContent=modules.find(m=>m[0]===current)[1];render();}else hub();}else page('lobby');for(const[id,value]of Object.entries(drafts)){const el=document.getElementById(id);if(el&&!el.readOnly)el.value=value;}protectPlayerControls();}chatRender();applyingRemote=false;save();});
async function backend(){if(window.Room)return window.Room;await new Promise((resolve,reject)=>{window.addEventListener('roomavailable',resolve,{once:true});setTimeout(()=>reject(new Error('The connection is still loading. Please try again.')),12000);});return window.Room;}
$('#create-room').addEventListener('click',async()=>{const b=$('#create-room');b.disabled=true;try{const r=await backend();await r.create($('#room-role').value);$('#connection-status').textContent='Room created. Send the invitation to your person.';}catch(e){report(e);}finally{b.disabled=false;}});
async function joinRoom(value){let id=value.trim();try{if(id.includes('://'))id=new URL(id).searchParams.get('room')||'';await(await backend()).join(id);}catch(e){report(e);}}
$('#join-room').addEventListener('click',()=>joinRoom($('#join-code').value));$('#copy-invite').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#invite-link').value);$('#copy-invite').textContent='Copied';}catch{$('#invite-link').select();}});$('#local-mode').addEventListener('click',()=>{if(online()){report(new Error('Open a new tab without an invitation to rehearse locally.'));return;}$('#connection-status').textContent='Same-screen rehearsal. Online changes are not sent.';document.querySelector('.ready-grid').scrollIntoView({behavior:'smooth'});});
const incomingRoom=new URLSearchParams(location.search).get('room');if(incomingRoom){$('#join-code').value=incomingRoom;joinRoom(incomingRoom);}
